refentry.refsect1:
&reftitle.returnvalues;


 &return.success;  Restituisce una string se PGSQL_DML_STRING viene passato
 tramite flags.

  &reftitle.examples;



    Esempio di pg_delete


<?php 
  $db = pg_connect('dbname=foo');
  // Questo è abbastanza sicuro, poiché viene effettuato l'escape di tutti i valori.
  // Tuttavia PostgreSQL supporta JSON/Array. Questi non sono
  // protetti né dall'escape né dalle query preparate.
  $res = pg_delete($db, 'post_log', $_POST, PG_DML_ESCAPE);
  if ($res) {
      echo "I dati POST sono stati eliminati: $res\n";
  } else {
      echo "L'utente deve aver inviato input errati\n";
  }
?>
